1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Soft duplicate detection on create. Household members are no longer rejected on create — a new
9	 * owner sharing an existing owner's household is admitted (its membership level is capped by
10	 * {@link CapMembershipLevel}) rather than blocked — so this step only raises a non-rejecting signal.
11	 *
12	 * <p>This step flags a weaker signal: a new owner whose {@code identityKey} <em>differs</em> from
13	 * an existing owner's while they share a last-name {@link Soundex} code and
14	 * the same {@code postcode}. In that case the owner is still created, but {@code possibleDuplicate}
15	 * is set true and {@code possibleDuplicateOf} is set to the matching owner's id (the lowest-id
16	 * match when several exist). Otherwise {@code possibleDuplicate} is false and
17	 * {@code possibleDuplicateOf} is left absent.
18	 *
19	 * <p>A matching identityKey is a <em>hard</em> duplicate already rejected upstream by
20	 * {@link RejectDuplicateIdentity}, so it never reaches here; two owners sharing a last name and
21	 * postcode but carrying different telephones have different identity keys and so are a soft match
22	 * rather than a rejection.
23	 *
24	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: sharing an
25	 * existing owner's last name and postcode is expected for it rather than a suspected duplicate.
26	 *
27	 * <p>Runs after the telephone and postcode have been normalized/assigned and before
28	 * {@link SaveOwner}, so the flags are fixed at creation time and returned on later reads.
29	 */
30	public class FlagPossibleDuplicate {
31	
32	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
33	        String lastName = owner.getLastName();
34	        String postcode = owner.getPostcode();
35	
36	        owner.setPossibleDuplicate(false);
37	        owner.setPossibleDuplicateOf(null);
38	
39	        if (Boolean.TRUE.equals(sharesHousehold)) {
40	            // Declared household member: expected to share a household, not a suspected duplicate.
41	            return;
42	        }
43	
44	        if (lastName == null || postcode == null) {
45	            return;
46	        }
47	
48	        String soundex = Soundex.of(lastName);
49	        String identityKey = OwnerIdentity.identityKey(owner);
50	
51	        Integer matchId = null;
52	        for (Owner existing : ownerRepository.findAll()) {
53	            if (existing.getId() == null || existing.getId().equals(owner.getId())) {
54	                continue;
55	            }
56	            if (Boolean.TRUE.equals(existing.getDeleted())) {
57	                // A soft-deleted owner is not a duplicate signal.
58	                continue;
59	            }
60	            if (!soundex.equals(Soundex.of(existing.getLastName()))) {
61	                continue;
62	            }
63	            if (!postcode.equals(existing.getPostcode())) {
64	                continue;
65	            }
66	            // A matching identityKey is a hard duplicate (rejected upstream); the soft signal is
67	            // for a different key that still shares the last-name soundex and postcode.
68	            if (identityKey.equals(OwnerIdentity.identityKey(existing))) {
69	                continue;
70	            }
71	            if (matchId == null || existing.getId() < matchId) {
72	                matchId = existing.getId();
73	            }
74	        }
75	
76	        if (matchId != null) {
77	            owner.setPossibleDuplicate(true);
78	            owner.setPossibleDuplicateOf(matchId);
79	        }
80	    }
81	}
