1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Single home for "how many owners were created on a given (business-day-adjusted)
10	 * registration date". Both {@link RejectOverDailyLimit} and {@link FlagBulkSignup}
11	 * key off this count at different thresholds; keeping the predicate here avoids
12	 * maintaining it in two places.
13	 */
14	final class OwnerDailyCount {
15	
16	    private OwnerDailyCount() {
17	    }
18	
19	    /**
20	     * Counts existing owners whose {@link Owner#getRegistrationDate()} equals
21	     * {@code registrationDate}. Called before the new owner is saved, so it is not
22	     * itself counted.
23	     */
24	    static long sharingRegistrationDate(OwnerRepository ownerRepository, LocalDate registrationDate) {
25	        return ownerRepository.findAll().stream()
26	                .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
27	                .count();
28	    }
29	}
